    cloze('أكمل اختبار الترتيب', 'اقرأ الجملة ___ من كلّ فقرة ___، فإن صنعت ___ فالتقرير مرتَّب.', ['الأولى', 'متتابعةً', 'ملخّصًا'], ['الأخيرة', 'منفردةً', 'جدولًا'], ''),
    cloze('أكمل هامش نورة', 'صفحة سامي مئة و___ كلمة، وصفحة ماريا مئتان و___؛ الأطول هنا هو ___.', ['ثمانون', 'عشر', 'الأوضح'], ['عشرون', 'ثلاثون', 'الأصعب'], ''),
    tf('نشرت الدار أحد عشر عنوانًا علميًّا جديدًا هذا العام.', 'نشرت الدار أحد عشر عنوانًا علميًّا جديدًا، مقابل تسعة في العام الماضي.', 'true', ''),
    tf('اقترح سامي كلفة للطباعة عند الطلب.', 'نوصي بدراسة تجربة الطباعة عند الطلب التي تجرّبها بعض الدور.', 'false', 'لا كلفة ولا موعد.'),
    tf('خالد وافق على التوصيات الثلاث.', 'ثلاث توصيات. الأولى: تطبع الدار العناوين عند الطلب.', 'ng', 'لم يقرأ خالد الصفحة بعد.'),
    tap('المس الصفة التي تحتاج إلى رقم', ['أثّر', 'ذلك', 'على', 'المبيعات', 'بشكل', 'ملحوظ'], 'ملحوظ', ''),
